#ifndef LIBRARIES_MQTT_H
#define LIBRARIES_MQTT_H

/* mqtt.library public API (Phase 2 slice 2). Checked in by hand - NOT
 * generated by sfdc (src/library/mqtt_lib.sfd is the generated-headers
 * source of truth for the function *prototypes*; this file supplies the
 * data types those prototypes reference).
 *
 * Callers: #include <libraries/mqtt.h> then #include <proto/mqtt.h>. The
 * Makefile's library-headers target copies this file to
 * build/include/libraries/mqtt.h so a single -Ibuild/include reaches both.
 *
 * Threading model: each APTR client handle returned by MQTT_CreateClient()
 * is owned by exactly one caller task - the one that created it. Every
 * other MQTT_* call on that handle (including MQTT_GetMessage/
 * MQTT_FreeMessage/MQTT_DeleteClient) must be made from that same task; the
 * handle's delivery MsgPort is a caller-task-owned port (see
 * src/library/mqtt_funcs.c), and MsgPorts are not safe to share across
 * tasks. Internally, each client is backed by a dedicated AmigaOS
 * subprocess that owns the bsdsocket.library connection and drives it
 * (bsdsocket handles are per-task) - callers never see that process
 * directly.
 */

#include <exec/types.h>
#include <exec/ports.h>

/* --- MQTT_CreateClient() connect options ---------------------------------
 * Mirrors the subset of src/core/mqtt_packet.h's mqtt_connect_opts that is
 * exposed at this layer - client id, optional username/password, keepalive,
 * clean-session. (Core also supports a Last Will; not exposed by this
 * slice's API - a future slice can extend struct MqttConnectOpts, which is
 * why every field here is named, not positional.) MQTT_CreateClient()
 * deep-copies every string out of this struct, so the caller may free or
 * reuse it immediately after the call returns. */
struct MqttConnectOpts {
    STRPTR mco_ClientID;      /* required; NUL-terminated */
    STRPTR mco_Username;      /* NULL = no username (and no password) */
    STRPTR mco_Password;      /* NULL = no password; ignored if Username is NULL */
    UWORD  mco_KeepAlive;     /* seconds; 0 disables keepalive PINGREQ */
    BOOL   mco_CleanSession;  /* TRUE = clean session (the common case) */
    BOOL   mco_AutoReconnect; /* FALSE (default/zeroed struct) = today's
                                  behaviour: an unexpected connection drop
                                  (transport error, keepalive timeout) leaves
                                  the client disconnected until the caller
                                  makes a fresh MQTT_Connect() call.
                                  TRUE = once MQTT_Connect() has succeeded,
                                  the client's subprocess re-establishes the
                                  connection itself on any unexpected drop -
                                  NOT an explicit MQTT_Disconnect() and NOT a
                                  failed *initial* MQTT_Connect() - retrying
                                  with exponential backoff (1s, 2s, 4s, ...
                                  capped at 32s, forever) and automatically
                                  re-issuing every MQTT_Subscribe() filter
                                  made since MQTT_Connect() on each successful
                                  reconnect. While reconnecting,
                                  MQTT_Publish()/MQTT_Subscribe() fail fast
                                  with MQTTERR_NOTCONNECTED (no queueing);
                                  messages already queued by MQTT_GetMessage()
                                  remain retrievable throughout.
                                  MQTT_Disconnect()/MQTT_DeleteClient() cancel
                                  an in-progress reconnect. */
};

/* --- Delivered message (MQTT_GetMessage/MQTT_FreeMessage) -----------------
 * One MqttMessage per PUBLISH received on a subscribed filter, queued on
 * the client's own delivery MsgPort and handed out FIFO by
 * MQTT_GetMessage(). Library-allocated (AllocVec, MEMF_PUBLIC) - always
 * free a message you got from MQTT_GetMessage() with MQTT_FreeMessage(),
 * never FreeVec() it yourself (it is one allocation together with its
 * topic/payload storage; the library's internal layout is not part of the
 * API). */
struct MqttMessage {
    struct Message mm_Msg;     /* mn_ReplyPort is unused - never ReplyMsg()
                                   this; free it with MQTT_FreeMessage() */
    STRPTR mm_Topic;           /* NUL-terminated */
    APTR   mm_Payload;         /* mm_PayloadLen bytes, NOT NUL-terminated -
                                   but one extra NUL byte is always allocated
                                   immediately after the payload, so
                                   ((STRPTR)mm_Payload)[mm_PayloadLen] == 0
                                   for callers that want to treat a text
                                   payload as a C string without copying */
    ULONG  mm_PayloadLen;
    UBYTE  mm_Qos;             /* 0 or 1 (QoS 2 is out of scope, see docs/PROTOCOL.md) */
    UBYTE  mm_Retain;          /* the broker's RETAIN flag on this PUBLISH */
};

/* --- MQTT_Publish() QoS semantics -----------------------------------------
 * qos 0: MQTT_Publish() returns 0 as soon as the PUBLISH packet has been
 *        written to the transport - no broker acknowledgement is waited
 *        for or expected.
 * qos 1: MQTT_Publish() returns 0 only after the broker's PUBACK for this
 *        publish arrives. If no PUBACK arrives within ~5s, the same
 *        PUBLISH is retransmitted with the DUP flag set, up to 3 times
 *        (so up to 4 sends total, ~15-20s worst case) before giving up and
 *        returning MQTTERR_TIMEOUT. Because each client handle's commands
 *        are synchronous, at most one QoS 1 publish is ever outstanding
 *        per handle - a second MQTT_Publish() call cannot be made until
 *        the first has returned.
 * qos 2 is out of scope (see docs/PROTOCOL.md) - MQTT_Publish() rejects it.
 *
 * --- MQTT_Subscribe() contract ----------------------------------------------
 * Returns 0 only after the broker's SUBACK grants the subscription. A
 * SUBACK return code of 0x80 (refused) yields MQTTERR_REFUSED; no SUBACK
 * within ~10s yields MQTTERR_TIMEOUT.
 *
 * --- Reconnecting-mode semantics (mco_AutoReconnect == TRUE only) ---------
 * While the client's subprocess is between an unexpected connection drop
 * and a restored connection, MQTT_Publish() and MQTT_Subscribe() both fail
 * fast with MQTTERR_NOTCONNECTED - neither is queued for later delivery.
 * MQTT_GetMessage() keeps returning any messages already queued (and any a
 * reconnect goes on to deliver once it succeeds); it never itself fails.
 * An MQTT_Connect() call made while already reconnecting also fails fast
 * with MQTTERR_NOTCONNECTED (a reconnect is already in progress in the
 * background; a second explicit MQTT_Connect() would just race it).
 *
 * --- Return / error codes --------------------------------------------------
 * 0 (MQTTERR_OK) on success; negative on failure. MQTT_Connect/
 * MQTT_Publish/MQTT_Subscribe pass through src/core's own negative
 * mqtt_err/mqtt_client_err codes where the failure originates there (see
 * src/core/mqtt_packet.h, src/core/mqtt_client.h - values -1..-4 and
 * -100..-104), and use the library-level codes below (-200 and lower) for
 * failures that happen above core, in mqtt.library's own subprocess/IPC
 * plumbing. */
#define MQTTERR_OK            0
#define MQTTERR_NOMEM       (-200) /* AllocVec/CreateMsgPort/process spawn
                                       failed for lack of memory */
#define MQTTERR_NOSTACK      (-201) /* CreateNewProcTags() failed to start
                                        the client's connection subprocess */
#define MQTTERR_NOTCONNECTED (-202) /* called before MQTT_Connect() succeeded,
                                        or after MQTT_Disconnect() */
#define MQTTERR_TIMEOUT      (-203) /* MQTT_Publish() at QoS 1: the broker
                                        never sent a PUBACK within the retry
                                        budget (3 DUP retransmits at ~5s
                                        intervals, so ~15-20s total).
                                        MQTT_Subscribe(): no SUBACK arrived
                                        within ~10s. */
#define MQTTERR_REFUSED      (-204) /* MQTT_Subscribe(): the broker's SUBACK
                                        granted the subscription a failure
                                        code (0x80) instead of a QoS */

#endif /* LIBRARIES_MQTT_H */
